1	import { ChildProcess, spawn } from "child_process";
2	import { EventEmitter } from "events";
3	
4	export class TexpressoProcessManager extends EventEmitter {
5	    private process: ChildProcess | null = null;
6	    private isRunning: boolean = false;
7	    private stdout_buffer: string = '';
8	
9	    constructor(
10	        private executablePath: string,
11	        private args: string[],
12	        private rootTex: string,
13	    ) {
14	        super();
15	        this.args.push(this.rootTex);
16	    }
17	
18	    public async start(): Promise<void> {
19	        if (this.isRunning) {
20	            throw new Error("Texpresso process is already running");
21	        }
22	
23	        try {
24	            this.process = spawn(this.executablePath, this.args, { stdio: "pipe" });
25	            this.isRunning = true;
26	
27	            this.process.stdout?.on("data", (data: Buffer) => {
28	                this.stdout_buffer += data;
29	                const lines = this.stdout_buffer.split("\n");
30	                this.stdout_buffer = lines.pop()?? '';
31	
32	                lines
33	                    .filter((line) => line != "")
34	                    .map((line) => {
35	                        try {
36	                            return JSON.parse(line);
37	                        } catch (e) {
38	                            return ["parse-fail", line];
39	                        }
40	                    })
41	                    .forEach((command_list) => {
42	                        const command = command_list[0];
43	                        const data = command_list.slice(1);
44	                        this.emit(command, data);
45	                    });
46	            });
47	
48	            this.process.stderr?.on("data", (data: Buffer) => {
49	                this.emit("stderr", data.toString());
50	            });
51	
52	            this.process.on("error", (error: Error) => {
53	                this.emit("error", error);
54	            });
55	
56	            this.process.on(
57	                "exit",
58	                (code: number | null, signal: NodeJS.Signals | null) => {
59	                    this.isRunning = false;
60	                    this.emit("exit", { code, signal });
61	                },
62	            );
63	
64	            // Wait for process to start
65	            await new Promise<void>((resolve, reject) => {
66	                const timeout = setTimeout(() => {
67	                    reject(new Error("Process start timeout"));
68	                }, 5000);
69	
70	                const stdout = this.process?.stdout;
71	                if (!stdout) {
72	                    clearTimeout(timeout);
73	                    reject(new Error("Process stdout not available"));
74	                    return;
